    fn trace<const N: usize>(cdf: &mut Cdf<N>, hash: &mut u64) {
        let mut writer = Writer::new();
        for step in 0..65 {
            writer.symbol((step * 7 + step / 3) % N, cdf).unwrap();
            for &value in cdf.inverse() {
                *hash = (*hash ^ u64::from(value)).wrapping_mul(1_099_511_628_211);
            }
        }
    }
